import json, os, re

d = os.environ.get('RLM_SESSION_DIR', '')
full_path = os.path.join(d, '../../sessions/' + os.path.basename(d) + '.jsonl')

with open(full_path) as f:
    messages = [json.loads(l) for l in f]

# Find demo and test grids by searching content
demo_grid = None
test_grid = None

for msg in messages:
    if 'content' in msg:
        content_text = ''
        # Handle both list and string content formats
        if isinstance(msg['content'], list):
            for part in msg['content']:
                if isinstance(part, dict) and 'text' in part:
                    content_text += part['text']
        elif isinstance(msg['content'], str):
            content_text = msg['content']

        # Search for demo pattern
        if 'Demo input grid' in content_text and demo_grid is None:
            # Extract input section
            m = re.search(r'Demo input grid:\s*(\[.*?"\]|\[.*?\])', content_text, re.DOTALL)
            if m:
                try:
                    demo_grid = json.loads(m.group(1))
                    print("Found demo input grid, size:", len(demo_grid), "x", len(demo_grid[0]) if demo_grid else 0)
                except:
                    pass

        # Search for Test input
        elif 'Test input' in content_text and test_grid is None:
            m = re.search(r'Test input\s*\[\s*\(\d+ x \d+\):\s*\{([^}]+)\}', content_text, re.DOTALL)
            if m:
                inner = m.group(1)
                try:
                    data = json.loads(inner)
                    if 'grid' in data:
                        test_grid = data['grid']
                        print(f"Found test input grid, size: {len(test_grid)} x {len(test_grid[0])}")
                except Exception as e:
                    pass

if demo_grid:
    print("\n=== Demo Grid ===")
    import pprint; pprint.pprint(demo_grid[:3])
if test_grid:
    print("\n=== Test Grid ===")
    import pprint; pprint.pprint(test_grid[:5])

